item.command:
/bin/bash -lc 'while IFS= read -r label; do
  case "$label" in
    '"'<empty>') arg=\"\" ;;
    '<space>') arg=\" \" ;;
    '<spaces>') arg=\"   \" ;;
    '<tab>') arg="'$'"'\\t' ;;
    '<newline>') arg="'$'"'a\\nb' ;;
    '<slash>') arg='/' ;;
    '<punct>') arg='"'!@#$%''^&*()'"' ;;
    '<mixed>') arg='a例b.com' ;;
    '<emoji>') arg='😀' ;;
    '<chinese>') arg='测试' ;;
    '<dotspace>') arg='. ' ;;
    '<dashspace>') arg='- ' ;;
    '<nbsp>') arg=' ' ;;
  esac
  printf 'CASE:%s\\n' \""'$label"
  /workspace/dataset/test4_executable "$arg"
  printf '"'%s\\n' '--'
done <<'EOF'
<empty>
<space>
<spaces>
<tab>
<newline>
<slash>
<punct>
<mixed>
<emoji>
<chinese>
<dotspace>
<dashspace>
<nbsp>
EOF"

